    targets = [c for c in opp.zones.battlefield
               if c.has(Tag.CREATURE) and not c.is_land()
               and safe_toughness(c) <= 3]
    if not targets:
        return
    t = max(targets, key=lambda c: safe_power(c))
    opp.zones.battlefield.remove(t)
    opp.zones.exile.append(t)
