def _mindspring_merfolk_etb(gs, card):
    """Mindspring Merfolk — {U} 1/1 Merfolk Wizard.
    'Exhaust — {X}{U}{U}, {T}: Draw X cards. Put a +1/+1 counter
     on each Merfolk creature you control.'"""
