    target = max(opp.zones.graveyard,
                  key=lambda c: getattr(c, 'cmc', 0))
    opp.zones.graveyard.remove(target)
    opp.zones.exile.append(target)
    gs._log(f"  Soul-Guide Lantern ETB: exile {target.name}")


