    card.tags.add(KWTag.FLYING)
    from data.card import Tag
    from engine.match_state import safe_power
    x = sum(1 for c in gs.zones.battlefield
            if c.has(Tag.CREATURE) and safe_power(c) >= 4)
    for _ in range(x):
        if gs.zones.library:
            top = gs.zones.library.pop(0)
