    for kw in (KWTag.VIGILANCE, KWTag.TRAMPLE, KWTag.HASTE):
        card.tags.add(kw)
    # X = 3 assumption
    card.counters = (card.counters or 0) + 3
    gs._log("  Goldvein Hydra: 3/3 VTH (X=3)")


