def _shock_land(gs, card):
    """Generic shock land handler — if life >= 5 pay 2 to untap,
    otherwise enter tapped."""
    if gs.life >= 5:
        gs.life -= 2
    else:
        card.tapped = True


def _blood_crypt_etb(gs, card):
    """Blood Crypt — Swamp Mountain shock."""
    _shock_land(gs, card)
    gs._log("  Blood Crypt: shock")


