    other_lands = [c for c in gs.zones.battlefield
                   if c.is_land() and c is not card]
    for t in other_lands[:2]:
        gs.zones.battlefield.remove(t)
        gs.zones.graveyard.append(t)
    gs._log("  Lotus Field: sac 2 lands, triple mana")


