    swamps = sum(1 for c in gs.zones.battlefield
                 if c is not card and c.is_land() and
                 "Swamp" in (c.type_line or ""))
    if swamps >= 3:
        crs = [c for c in gs.zones.graveyard if c.has(Tag.CREATURE)]
