# ═══════════════════════════════════════════════════════════════════
# Standard Batch — Worldsoul's Rage
# ═══════════════════════════════════════════════════════════════════

def _worldsouls_rage_spell(gs, card):
    """Worldsoul's Rage — {X}{R}{G} Sorcery.
    'Worldsoul's Rage deals X damage to any target. Put up to X land
     cards from your hand and/or graveyard onto the battlefield
     tapped.'

    Goldfish: X=3 default (typical 5-mana finisher window). Damage
    uses the shared any-target helper. For the ramp half, prefer
    graveyard lands first (recycles otherwise-dead cards) then hand
    lands, up to X total, each entering tapped."""
    x = 3
    _damage_any_helper(gs, x)
    placed = 0
    # Graveyard lands first
    gy_lands = [c for c in gs.zones.graveyard if c.is_land()]
    for land in gy_lands:
        if placed >= x:
            break
        gs.zones.graveyard.remove(land)
        gs.zones.battlefield.append(land)
        land.tapped = True
        land.turn_entered = gs.turn
        gs.mana_pool.flex += 1
        placed += 1
    # Then hand lands
    while placed < x:
        land = next((c for c in gs.zones.hand if c.is_land()), None)
        if land is None:
            break
        gs.zones.hand.remove(land)
        gs.zones.battlefield.append(land)
        land.tapped = True
        land.turn_entered = gs.turn
        gs.mana_pool.flex += 1
        placed += 1
    gs._log(f"  Worldsoul's Rage (X={x}): {x} dmg + {placed} lands tapped")


_SPELL_HANDLERS.update({
    "Worldsoul's Rage": _worldsouls_rage_spell,
})


# SKIP: Gran-Gran ({U} Legendary Creature) — needs static-ability +
# tap-trigger paths, not ETB/spell. "Whenever Gran-Gran becomes
# tapped, draw a card, then discard a card." is a tap trigger and
# "Noncreature spells you cast cost {1} less..." is a static cost
# reduction gated on Lesson count in graveyard. Requires static
# ability handling, not a log-only stub.


def _firebending_lesson(gs, card):
    """Firebending Lesson — {R} Instant — Lesson.
    'Kicker {4} (You may pay an additional {4} as you cast this
     spell.) Firebending Lesson deals 2 damage to target creature.
     If this spell was kicked, it deals 5 damage to that creature
     instead.'

    Goldfish kicker heuristic: same as Burst Lightning — if we have
    5+ lands in play, assume we paid the kicker (total cost 5).
    Targets creature only, so mirror Torch the Tower's target-a-
    creature kill path."""
    from data.card import Tag
    from engine.match_state import safe_power, safe_toughness
    lands = sum(1 for c in gs.zones.battlefield if c.is_land())
    dmg = 5 if lands >= 5 else 2
    opp = getattr(gs, "_match_opp", None)
    if opp is None:
        gs._log(f"  Firebending Lesson: {dmg} dmg (no opp modeled)")
        return
    killable = [c for c in opp.zones.battlefield
                if c.has(Tag.CREATURE) and not c.is_land()
                and safe_toughness(c) <= dmg]
    if killable:
        t = max(killable, key=lambda c: safe_power(c))
        opp.zones.battlefield.remove(t)
        opp.zones.graveyard.append(t)
        gs._log(f"  Firebending Lesson: {dmg} dmg kills {t.name}")
    else:
        gs._log(f"  Firebending Lesson: {dmg} dmg (no legal kill)")


_SPELL_HANDLERS.update({
    "Firebending Lesson": _firebending_lesson,
})


def _harvester_of_misery_etb(gs, card):
    """Harvester of Misery — {3}{B}{B} 5/4 Spirit.
    'Menace. When this creature enters, other creatures get -2/-2
     until end of turn. {1}{B}, Discard: target creature -2/-2 EOT.'"""
    from data.card import Tag
    from engine.keywords import KWTag
    card.tags.add(KWTag.MENACE)

    opp = getattr(gs, "_match_opp", None)
    sides = [gs.zones.battlefield]
    if opp is not None:
        sides.append(opp.zones.battlefield)

    own_deaths = 0
    opp_deaths = 0
    survivors = []
    for bf in sides:
        for c in list(bf):
            if c is card or c.is_land() or not c.has(Tag.CREATURE):
                continue
            c.counters = (c.counters or 0) - 2
            if c.effective_toughness() <= 0:
                bf.remove(c)
                if bf is gs.zones.battlefield:
                    gs.zones.graveyard.append(c)
                    own_deaths += 1
                else:
                    opp.zones.graveyard.append(c)
                    opp_deaths += 1
            else:
                survivors.append(c)
    # Revert counters on survivors (EOT simulation, matches Massacre Wurm pattern)
    for c in survivors:
        c.counters = (c.counters or 0) + 2
    gs._log(f"  Harvester of Misery ETB: -2/-2 sweep "
            f"({own_deaths} own, {opp_deaths} opp)")


_ETB_HANDLERS.update({
    "Harvester of Misery": _harvester_of_misery_etb,
})


def _combustion_technique(gs, card):
    """Combustion Technique — {1}{R} Instant — Lesson.
    'Combustion Technique deals damage equal to 2 plus the number of
     Lesson cards in your graveyard to target creature. If that
     creature would die this turn, exile it instead.'"""
    from data.card import Tag
    from engine.match_state import safe_power, safe_toughness
    lessons_in_gy = sum(
        1 for c in gs.zones.graveyard
        if "lesson" in (c.type_line or "").lower()
    )
    dmg = 2 + lessons_in_gy
    opp = getattr(gs, "_match_opp", None)
    if opp is None:
        gs._log(f"  Combustion Technique: {dmg} dmg "
                f"({lessons_in_gy} Lessons in GY, no opp modeled)")
        return
    killable = [c for c in opp.zones.battlefield
                if c.has(Tag.CREATURE) and not c.is_land()
                and safe_toughness(c) <= dmg]
    if killable:
        t = max(killable, key=lambda c: safe_power(c))
        opp.zones.battlefield.remove(t)
        opp.zones.exile.append(t)  # "exile it instead" replacement
        gs._log(f"  Combustion Technique: {dmg} dmg exiles {t.name} "
                f"({lessons_in_gy} Lessons in GY)")
    else:
        gs._log(f"  Combustion Technique: {dmg} dmg "
                f"(no legal kill, {lessons_in_gy} Lessons in GY)")


_SPELL_HANDLERS.update({
    "Combustion Technique": _combustion_technique,
})


